def transform(grid):
    out = [row[:] for row in grid]
    color = next(v for row in grid for v in row if v != 0)

    # Normalize the disrupted row patterns by transferring isolated cells
    # toward the recurring pattern in the surrounding rows.
    variable_cols = (0, 1, 3, 4, 6, 7, 9, 10, 12, 13)
    for r in range(1, len(grid), 2):
        for c in variable_cols:
            if grid[r][c] == color:
                continue
            # Preserve the solid vertical stripe cells; only repair a gap
            # when both neighboring odd rows support the filled cell.
            if 0 < r < len(grid) - 1:
                if grid[r - 1][c] == color and grid[r + 1][c] == color:
                    out[r][c] = color
    return out
