    h, w = len(grid), len(grid[0])
    color = next(v for row in grid for v in row if v != 0)

    # Smooth the variable cells across the repeated horizontal bands.
    for r in range(1, h, 2):
        for c in range(w):
            if c % 3 == 2:
                continue
            neighbors = [grid[rr][c] for rr in (r - 2, r, r + 2)
                         if 0 <= rr < h and rr % 2 == 1]
            if neighbors and neighbors.count(color) > len(neighbors) / 2:
                out[r][c] = color
            elif neighbors:
                out[r][c] = 0
    return out
